const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;function sync(){document.body.classList.toggle('paused',paused);window.dispatchEvent(new CustomEvent('motionchange',{detail:{paused}}))}sync();reduced.addEventListener('change',e=>{paused=e.matches;sync()});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal,.approach-grid,.eval-lab,.timeline article').forEach(el=>{el.classList.add('reveal');observer.observe(el)});
const progressBar=document.querySelector('.progress');let progressFrame=0,progressMax=1;
function measureProgress(){progressMax=Math.max(1,document.documentElement.scrollHeight-innerHeight);queueProgress()}
function queueProgress(){if(!progressFrame)progressFrame=requestAnimationFrame(()=>{progressFrame=0;progressBar.style.transform='scaleX('+Math.min(1,scrollY/progressMax)+')'})}
addEventListener('scroll',queueProgress,{passive:true});addEventListener('resize',measureProgress,{passive:true});new ResizeObserver(measureProgress).observe(document.body);measureProgress();function time(){document.querySelector('#time').textContent=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' IST'}time();setInterval(time,60000);

// Muted project walkthroughs loop automatically while the page is visible.
const walkthroughs=[...document.querySelectorAll('.project-video')],visibleWalkthroughs=new Set(),mobileVideo=matchMedia('(max-width:899px)'),pendingPlayback=new WeakSet();
function selectVideoSources(){walkthroughs.forEach(video=>{const source=video.querySelector('source');source.dataset.desktop=source.dataset.desktop||source.getAttribute('src');const next=mobileVideo.matches?source.dataset.desktop.replace('.mp4','-mobile.mp4'):source.dataset.desktop;if(source.getAttribute('src')!==next){video.pause();source.setAttribute('src',next);video.load()}});syncWalkthroughs()}
function canPlay(video){return !reduced.matches&&!document.hidden&&visibleWalkthroughs.has(video)}
function syncWalkthroughs(){walkthroughs.forEach(video=>{video.muted=true;video.autoplay=false;if(!canPlay(video))video.pause();else if(video.paused&&!pendingPlayback.has(video)){pendingPlayback.add(video);video.play().then(()=>{if(!canPlay(video))video.pause()}).catch(()=>{}).finally(()=>pendingPlayback.delete(video))}})}
const videoVisibility=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting&&entry.intersectionRatio>=.15)visibleWalkthroughs.add(entry.target);else visibleWalkthroughs.delete(entry.target)});syncWalkthroughs()},{threshold:.15});walkthroughs.forEach(video=>videoVisibility.observe(video));
reduced.addEventListener('change',syncWalkthroughs);document.addEventListener('visibilitychange',syncWalkthroughs);mobileVideo.addEventListener('change',selectVideoSources);selectVideoSources();
